<script type="text/javascript">

     var neuro_id =$('#neuro_id').val();
     var neuro_date =$('#visit_date').val();

    function updateInfantScore(event, element, mainIndex, objectIndex){
       // $('#infants_tab .total_score').text("Assessed").removeClass('label-danger').addClass('label-success');
        var cell = event.target;
        var cellRect = cell.getBoundingClientRect();
        var cellWidth = cellRect.width;
        var clickX = event.clientX - cellRect.left;
        if (clickX < cellWidth / 2) {
          
            if (!$(element).hasClass('half-mark')) {
                handleMarking(element, mainIndex, objectIndex, 0.5,'infants');
            } else {
                $(element).removeClass('half-mark').removeClass('red').removeClass('green');
                updateResultData(mainIndex, objectIndex, 0,'infants');
            }
        } else {
            
            if (!$(element).hasClass('full-mark')) {
                handleMarking(element, mainIndex, objectIndex, 1,'infants');
            } else {
                $(element).removeClass('full-mark').removeClass('red').removeClass('green');
                updateResultData(mainIndex, objectIndex, 0,'infants');
            }
        }
        
    }

    function handleMarking(element, mainIndex, objectIndex, mark, type) {

        bootbox.dialog({
            message: "<p>Status</p>",
            size: 'small',
            buttons: {
                pass: {
                    label: "Green",
                    className: 'btn-success',
                    callback: function() {
                        var color = 'green';
                        // handleMarking(clickX, cellWidth, element, color,  mainIndex, objectIndex);
                        addMarkToElement(element, mainIndex, objectIndex, mark, 'green',type);
                    }
                },
                fail: {
                    label: "Red",
                    className: 'btn-danger',
                    callback: function() {
                        var color = 'red';
                        addMarkToElement(element, mainIndex, objectIndex, mark, 'red',type);
                         // handleMarking(clickX, cellWidth, element, color,  mainIndex, objectIndex);
                    }
                }
            }
        });
    }

    function addMarkToElement(element, mainIndex, objectIndex, mark, color,type){
        var class_to_add = '';
        var class_to_remove = '';
        if (mark == 0.5) {
            class_to_add = 'half-mark';
            class_to_remove = 'full-mark';
        } else {
            class_to_add = 'full-mark';
            class_to_remove = 'half-mark';
        }
        $(element).removeClass(class_to_remove).removeClass('red').removeClass('green');
        $(element).addClass(class_to_add).addClass(color);
        updateResultData(mainIndex, objectIndex, mark, type, color);
        if (!$(element).siblings('td').hasClass('half-mark') && !$(element).siblings('td').hasClass('full-mark')) {
            $(element).prevAll('td').not('.not-score').each(function() {
                $(this).addClass('full-mark').addClass(color);
                updateResultData($(this).data('main_index'), $(this).data('sub_index'), 1, type, color);
            });
        }
    }


    
    function updateResultData(mainIndex, objectIndex, value, type, select_color=''){
      
        var postURL = " ";
        if (type == 'preschoolers') {
            postURL = "{{ action('Registration\NeuroController@preschoolersChart') }}";
        }else{
              postURL = "{{ action('Registration\NeuroController@infantChart') }}";
        }
        // console.log('asdgsdfh');
        // if (!Array.isArray(resultData[mainIndex])) {
        //   resultData[mainIndex] = [];
        // }
        // if (typeof(resultData[mainIndex][objectIndex]) !== 'undefined') {
        //     resultData[mainIndex][objectIndex] = null;
        // }
        $.ajax({
            headers: {
              'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
            },
            type: 'POST',
            async: false,
            url: postURL,
            // contentType: "application/json",
            data: {main_index: mainIndex, object_index: objectIndex, res_value: value, neuro_visit_id: neuro_id, visit_date: neuro_date, color: select_color},
            success: function(data) {
                    $("#msg").html(data.msg);         
              },
            failure: function(response) {
              Showalert('error', 'Something went wrong, Please try again later...!');
            }
        });
  
    } 




</script>
